from typing import override

from ai.backend.common.data.entity.types import EntityIdentifier, EntityType

__all__ = (
    "AutoGeneratedFileEntityType",
    "AutoGeneratedFileID",
)


class AutoGeneratedFileEntityType(EntityType):
    @override
    @classmethod
    def name(cls) -> str:
        return "auto_generated_file"

    @override
    @classmethod
    def description(cls) -> str:
        return "A file an entity places in its sessions."


class AutoGeneratedFileID(EntityIdentifier):
    @override
    def entity_type(self) -> EntityType:
        return AutoGeneratedFileEntityType()
